#include <stdio.h>

typedef struct T {
    int x;
    struct T *p;
    struct T *q;
} T;

int k = 0;
int r = 0;

void f(T *t) {
    if (t == NULL) {
        return;
    }
    f(t->p);
    f(t->q);
    if (++k == 3) {
        r = t->x;
    }
}

int main(void) {
    T dn = {0, NULL, NULL};
    T en = {0, NULL, NULL};
    T cn = {53, NULL, NULL};
    T bn = {12, &dn, &en};
    T an = {64, &bn, &cn};

    f(&an);
    printf("%d", r);
    return 0;
}

