#include <stdio.h>

void funcOne(int *p) {
    *p = 50;
}

void funcTwo(int p) {
    p = 60;
}

void funcThree(int p[]) {
    int *q = p;
    printf("3. %d\n", *q);
    printf("4. %d", *(q + 3));
}

int main(void) {
    int i = 30;
    int arr[] = {2, 4, 6, 8, 10};

    funcOne(&i);
    printf("1. %d\n", i);

    funcTwo(i);
    printf("2. %d\n", i);

    funcThree(arr);
    return 0;
}

다음 Java 코드의 실행 결과를 쓰시오.
class X {
    int a;
    private int b;
    protected int c;

    X(int aa, int bb, int cc) {
        a = aa;
        b = bb;
        c = cc;
    }

    int f() {
        return a + b + c;
    }
}

class Y extends X {
    Y(int aa, int bb, int cc) {
        super(aa, bb, cc);
    }

    @Override
    public int f() {
        return a * c;
    }
}

public class Main {
    public static void main(String[] args) {
        X obj1 = new X(1, 5, 3);
        Y obj2 = new Y(10, 30, 50);
        System.out.print(obj1.f() + obj2.f());
    }
}
